import{_ as t,o as a,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Remove Hastag Collection","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-21-remove-hashtag-collection/spec.md","filePath":"feature/content-task-workflow/3-6-21-remove-hashtag-collection/spec.md"}'),r={name:"feature/content-task-workflow/3-6-21-remove-hashtag-collection/spec.md"};function i(s,e,c,h,l,d){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="uc-—-remove-hastag-collection" tabindex="-1">UC — Remove Hastag Collection <a class="header-anchor" href="#uc-—-remove-hastag-collection" aria-label="Permalink to &quot;UC — Remove Hastag Collection&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.21</td></tr><tr><td>Feature</td><td>Remove Hastag Collection</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR, CLIENT, MANAGER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Xóa hashtag cũ khỏi Collection — soft delete, hashtag đã áp dụng vào bài cũ không bị xóa theo.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator hoặc Client, tôi muốn xóa hashtag không còn dùng, nhưng không muốn ảnh hưởng các bài đăng cũ đã dùng hashtag đó.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Xóa hashtag khỏi Collection (<code>status=removed</code>) — <strong>soft delete</strong>.</li><li>Hashtag đã gắn vào Task cũ (FR 3.6.17) vẫn giữ nguyên hiển thị ở bài đăng đó, chỉ không còn xuất hiện trong danh sách chọn mới.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Nút Delete trong list Hashtag, confirm dialog.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /api/v1/workspaces/{id}/hashtags/{hashtagId}</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: null }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Không có quyền → 403 <code>FORBIDDEN</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Xóa hashtag đang <code>isRequired=true</code> do Client set → Manager/Creator có thể xóa được (không cần Client tự xóa), nhưng nên cảnh báo rõ đây là hashtag bắt buộc trước khi confirm.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Soft delete thành công, không ảnh hưởng hashtag đã dùng ở Task cũ.</li></ul><h2 id="implementation-contract-—-2026-10-10" tabindex="-1">Implementation contract — 2026-10-10 <a class="header-anchor" href="#implementation-contract-—-2026-10-10" aria-label="Permalink to &quot;Implementation contract — 2026-10-10&quot;">​</a></h2><p>This delivery uses the existing workspace hashtag&#39;s <code>deletedAt</code>/<code>deletedBy</code> fields for soft removal. Manager may remove any entry. Creator may remove own ordinary entries and any required Client entry. Client may remove own entries. Other roles and cross-workspace IDs are denied without exposing the entry. The API checks membership and this matrix again when <code>DELETE /api/v1/workspaces/{workspaceId}/hashtags/{hashtagId}</code> is called.</p><p>The collection response includes the JPA version; the UI sends it as <code>expectedVersion</code>. A stale version returns <code>HASHTAG_CHANGED</code>; the UI loads the active entry and requires the user to review its updated purpose, scope and required warning before confirming again. Repeated removal returns <code>HASHTAG_ALREADY_REMOVED</code>; missing/cross-workspace entries return <code>HASHTAG_NOT_FOUND</code>. Successful removal returns HTTP 200 with null data. It does not mutate post/task snapshots.</p><p>Required-tag warning includes its MediaCampaign scope (the current scope mapping for EVENT_SPECIFIC tags) and explains the effect on future selection. Ordinary entries also explain that previously applied hashtags remain unchanged.</p><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a></p>`,26)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
